import { useRef, useState, type SubmitEvent } from 'react';

const fields = [
    { key: 'name', label: 'Endpoint', required: true },
    { key: 'branch', label: 'Branch', required: false },
    { key: 'type', label: 'Type', required: false }
  ] as const;
type Key = typeof fields[number]['key'];
type Values = Record<Key, string | null>;
type Row = Values & { id: number };
type Diff = { label: string; before: string | null; after: string | null };
type Change = { id: number; version: number; diffs: Diff[] };
const seed: Row[] = [
    { id: 1, name: 'NH-WS-014', branch: 'North Hub', type: 'Workstation' },
    { id: 2, name: 'HO-LT-007', branch: 'Harbor Office', type: 'Laptop' }
  ];
function cleanForWrite(form: FormData): Values {
  return Object.fromEntries(fields.map(field => [field.key, String(form.get(field.key) ?? '').trim() || null])) as Values;
}
function toCsvCell(value: string | null) {
  const text = String(value ?? '');
  const safe = /^[\s]*[=+@\x2D]/.test(text) ? "'" + text : text;
  return '"' + safe.replaceAll('"', '""') + '"';
}
function exportCsv(visible: Row[]) {
  const lines = [fields.map(field => field.label), ...visible.map(row => fields.map(field => row[field.key]))];
  const csv = lines.map(line => line.map(toCsvCell).join(',')).join('\r\n');
  const url = URL.createObjectURL(new Blob(['\uFEFF', csv], { type: 'text/csv;charset=utf-8' }));
  const link = document.createElement('a');
  link.href = url;
  link.download = 'endpoint-register.csv';
  link.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

export default function ConfigDrivenRegister() {
  const editor = useRef<HTMLDialogElement>(null);
  const audit = useRef<HTMLDialogElement>(null);
  const [rows, setRows] = useState(seed);
  const [search, setSearch] = useState('');
  const [editing, setEditing] = useState<Row | null>(null);
  const [formVersion, setFormVersion] = useState(0);
  const [historyId, setHistoryId] = useState<number | null>(null);
  const [history, setHistory] = useState<Change[]>([]);
  const [notice, setNotice] = useState('');
  const visible = rows.filter(row => fields.some(field => (row[field.key] ?? '').toLowerCase().includes(search.trim().toLowerCase())));
  const changes = history.filter(change => change.id === historyId).slice().reverse();
  function edit(row: Row | null) {
    setEditing(row);
    setFormVersion(version => version + 1);
    editor.current?.showModal();
  }
  function save(event: SubmitEvent<HTMLFormElement>) {
    event.preventDefault();
    const clean = cleanForWrite(new FormData(event.currentTarget));
    if (fields.some(field => field.required && !clean[field.key])) { setNotice('Enter the required endpoint name.'); return; }
    const id = editing?.id ?? Math.max(0, ...rows.map(row => row.id)) + 1;
    const updated = { ...clean, id };
    const diffs = fields.filter(field => (editing?.[field.key] ?? null) !== clean[field.key])
      .map(field => ({ label: field.label, before: editing?.[field.key] ?? null, after: clean[field.key] }));
    setRows(previous => editing ? previous.map(row => row.id === id ? updated : row) : [...previous, updated]);
    if (diffs.length) setHistory(previous => [...previous, { id, version: previous.filter(change => change.id === id).length + 1, diffs }]);
    setNotice(diffs.length ? 'Saved ' + clean.name + '.' : 'No fields changed.');
    editor.current?.close();
  }
  return <section aria-label="Endpoint register" className="grid gap-3 p-3 text-start text-sm">
    <label className="grid gap-1">Search register<input type="search" className="min-w-0 rounded-sm border border-strong bg-surface p-2 text-ink" value={search} onChange={event => setSearch(event.target.value)}/></label>
    <div className="flex flex-wrap items-center gap-2"><button type="button" className="rounded-sm border border-strong bg-surface px-3 py-2 text-ink hover:bg-subtle" onClick={() => edit(null)}>Create record</button>
      <button type="button" className="rounded-sm border border-strong bg-surface px-3 py-2 text-ink hover:bg-subtle" onClick={() => exportCsv(visible)}>Export CSV</button></div>
    <table className="w-full table-fixed text-xs"><thead><tr>
      {fields.map(field => <th scope="col" className="break-words border-b border-hairline p-1 text-start align-top [overflow-wrap:anywhere]" key={field.key}>{field.label}</th>)}<th scope="col" className="break-words border-b border-hairline p-1 text-start align-top [overflow-wrap:anywhere]">Actions</th>
    </tr></thead><tbody>{visible.map(row => <tr key={row.id}>
      {fields.map(field => <td className="break-words border-b border-hairline p-1 text-start align-top [overflow-wrap:anywhere]" key={field.key}>{row[field.key] ?? '—'}</td>)}
      <td className="break-words border-b border-hairline p-1 text-start align-top [overflow-wrap:anywhere]"><button type="button" className="block min-h-6 min-w-6 px-1 text-accent underline" aria-label={'Edit ' + row.name} onClick={() => edit(row)}>Edit</button>
        <button type="button" className="block min-h-6 min-w-6 px-1 text-accent underline" aria-label={'History for ' + row.name} onClick={() => { setHistoryId(row.id); audit.current?.showModal(); }}>History</button></td>
    </tr>)}</tbody></table>{!visible.length && <p>No matching records.</p>}
    <dialog ref={editor} aria-label="Record editor" className="m-auto w-[min(25rem,calc(100%-2rem))] max-w-full rounded-sm border border-strong bg-surface p-3 text-ink backdrop:bg-black/40" onClick={event => { if (event.target === editor.current) editor.current?.close(); }}>
      <form key={formVersion} onSubmit={save} className="grid gap-2"><h3>{editing ? 'Edit record' : 'Create record'}</h3>
        {fields.map(field => <label className="grid gap-1" key={field.key}>{field.label}
          <input className="min-w-0 rounded-sm border border-strong bg-surface p-2 text-ink" name={field.key} required={field.required} defaultValue={editing?.[field.key] ?? ''} maxLength={120}/></label>)}
        <div className="flex flex-wrap items-center gap-2"><button className="rounded-sm border border-strong bg-surface px-3 py-2 text-ink hover:bg-subtle">Save record</button><button type="button" className="rounded-sm border border-strong bg-surface px-3 py-2 text-ink hover:bg-subtle" onClick={() => editor.current?.close()}>Cancel</button></div>
      </form></dialog>
    <dialog ref={audit} aria-label="Field history" className="fixed inset-y-0 m-0 ms-auto h-full max-h-full w-[min(22rem,100%)] border-s border-strong bg-surface p-3 text-ink backdrop:bg-black/40" onClick={event => { if (event.target === audit.current) audit.current?.close(); }}>
      <h3>Field history</h3>{!changes.length && <p>No changes recorded in this session.</p>}
      {changes.map(change => <section className="my-2" key={change.version}><h4>Revision {change.version}</h4><dl>
        {change.diffs.map(diff => <div className="py-1" key={diff.label}><dt>{diff.label}</dt><dd><del>{diff.before ?? 'null'}</del> → <ins>{diff.after ?? 'null'}</ins></dd></div>)}
      </dl></section>)}<button type="button" className="rounded-sm border border-strong bg-surface px-3 py-2 text-ink hover:bg-subtle" onClick={() => audit.current?.close()}>Close history</button>
    </dialog><p role="status" className="min-h-5 text-xs text-accent">{notice}</p>
  </section>;
}
